#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[])
{
    // Too many arguments (> 65)
    if (argc > 65) {
        puts("TOO_MANY");
        return 0;
    }

    // Not enough arguments (< 2)
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    // Any argument longer than 1024 characters?
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 1024) {
            puts("TOO_LONG");
            return 0;
        }
    }

    // Compute longest common prefix among all arguments, including argv[0]
    const char *ref = argv[0];
    size_t pref_len = strlen(ref);

    for (int i = 1; i < argc; ++i) {
        size_t j = 0;
        while (j < pref_len && ref[j] && argv[i][j] && ref[j] == argv[i][j]) {
            ++j;
        }
        pref_len = j;
        if (pref_len == 0) {
            break;
        }
    }

    // Output the prefix followed by a newline
    if (pref_len > 0) {
        fwrite(ref, 1, pref_len, stdout);
    }
    putchar('\n');
    return 0;
}
